package net.epicfight_dd.client.particle;

import net.minecraft.client.multiplayer.ClientLevel;
import net.minecraft.client.particle.*;
import net.minecraft.core.particles.SimpleParticleType;
import org.jetbrains.annotations.NotNull;

// CODE GENERATED BY AI (gez. Nexo)

public class HungerIndicatorParticle extends TextureSheetParticle {

    protected HungerIndicatorParticle(ClientLevel level, double x, double y, double z,
                                      double dx, double dy, double dz, SpriteSet sprites) {
        super(level, x, y, z, dx, dy, dz);
        this.pickSprite(sprites);
        this.lifetime = 20 + this.random.nextInt(8);
        this.quadSize = 0.10F + this.random.nextFloat() * 0.04F;
        this.gravity = 0.0F;
        this.xd = dx * 0.2D;
        this.yd = 0.04D + Math.abs(dy) * 0.2D;
        this.zd = dz * 0.2D;
    }

    @Override
    public void tick() {
        super.tick();
        this.alpha = 1.0F - (float) this.age / (float) this.lifetime;
    }

    @Override
    public @NotNull ParticleRenderType getRenderType() {
        return ParticleRenderType.PARTICLE_SHEET_TRANSLUCENT;
    }

    public static class Provider implements ParticleProvider<SimpleParticleType> {
        private final SpriteSet sprites;
        public Provider(SpriteSet sprites) { this.sprites = sprites; }

        @Override
        public Particle createParticle(@NotNull SimpleParticleType type, @NotNull ClientLevel level,
                                       double x, double y, double z, double dx, double dy, double dz) {
            return new HungerIndicatorParticle(level, x, y, z, dx, dy, dz, sprites);
        }
    }
}
